local GiftEventCenter = require "amf.feature.giftpackage.event.GiftEventCenter"
local PromoteFullPackageManager = class("PromoteFullPackageManager")
local promoteFullModel

function PromoteFullPackageManager:ctor()
    self._needUpdate = true
end

function PromoteFullPackageManager:initialize()
    local PromoteFullModel = require "amf.feature.promotefullpackage.model.PromoteFullModel"
    promoteFullModel = PromoteFullModel:create()
    GiftEventCenter:registerFeature(self)
end

function PromoteFullPackageManager:tryLoadMaintenance()
    if self._maintenanceEnabled == nil then
        self._maintenanceEnabled = MaintenanceManager:getInstance():isEnabledInGroup('Max_Level_Gift_Toggle', 'ON1') or EnvUtil:isWindows() or EnvUtil:isMac()
    end
end

--符合开关开条件
function PromoteFullPackageManager:isFeatureBasicallyEnabled()
    local PersonalRecommend = require 'amf.feature.giftpackage.common.PersonalRecommend'
    if not PersonalRecommend:isEnabled() then return end

    self:tryLoadMaintenance()
    return self._maintenanceEnabled
end

--符合后端周期开启条件，能开大藤蔓上的花icon
function PromoteFullPackageManager:isFeatureOpen(careLevel)
    if not self:isFeatureBasicallyEnabled() then return end
    return promoteFullModel and promoteFullModel:isFeatureOpen(careLevel)
end

function PromoteFullPackageManager:onBuyFastPackage(commonGiftData)
    if not promoteFullModel then return end
    if commonGiftData then
        local afterBuyCd = commonGiftData:getExtraValue("afterBuyCd")
        if afterBuyCd then
            afterBuyCd = tonumber(afterBuyCd) or (24 * 3600 * 1000)
            local nextRefreshTime = math.floor(afterBuyCd / 1000) + TimeKit:timeInSec()
            promoteFullModel:syncNextRefreshTime(nextRefreshTime, true)
        end
    end
end

function PromoteFullPackageManager:syncInfoFromFastPackage(commonGiftData)
    if not promoteFullModel then return end
    if commonGiftData then
        local nextRefreshTs = commonGiftData:getExtraValue("nextRefreshTs")
        if nextRefreshTs then
            nextRefreshTs = tonumber(nextRefreshTs) or 0
            local nextRefreshTime = math.floor(nextRefreshTs / 1000)
            promoteFullModel:syncNextRefreshTime(nextRefreshTime)
        end
    end
end

function PromoteFullPackageManager:needUpdateMainInfo()
    if self._needUpdate then return true end
    local nextRefreshTime = promoteFullModel:getNextRefreshTime()
    if nextRefreshTime > 0 then
        return nextRefreshTime < TimeKit:timeInSec()
    end
end

function PromoteFullPackageManager:onActEnterMainScene(event)
    if not self:isFeatureBasicallyEnabled() then return end

    if self:needUpdateMainInfo() then
        self:loadMainInfo()
    end
end

function PromoteFullPackageManager:loadMainInfo()
    promoteFullModel:requestServerPackage():next(function()
        self._needUpdate = false
        if promoteFullModel:isFeatureOpen() then
            self:addTimeCountAlarm()
        end
    end)
end

function PromoteFullPackageManager:addTimeCountAlarm()
    self:removeAlarm()

    local endTime = promoteFullModel:getEndTime()
    local now = TimeKit:timeInSec()
    local interval = endTime - now
    if interval <= 0 then return end
    self.tickId = TimerUtil.addAlarm(function()
        self:onExpired()
    end, interval, 1)
end

function PromoteFullPackageManager:onExpired()
    self._needUpdate = true
    self:removeAlarm()
end

function PromoteFullPackageManager:removeAlarm()
    if self.tickId then
        TimerUtil.removeAlarm(self.tickId)
        self.tickId = nil
    end
end

function PromoteFullPackageManager:getLevelId()
    return promoteFullModel:getLevelId()
end 

return PromoteFullPackageManager
